& \frac{\mathrm{v}_{\mathrm{x}} \mathrm{dv}_{\mathrm{x}}}{\mathrm{dr}}=\frac{\mu_0 \mathrm{Iq}}{2 \pi \mathrm{ m}} \frac{\mathrm{v}_{\mathrm{y}}}{\mathrm{r}} \\
& \int_{v_0}^0 \frac{\mathrm{v}_{\mathrm{x}} \mathrm{dv}_{\mathrm{x}}}{\sqrt{\mathrm{v}_0^2-\mathrm{v}_{\mathrm{x}^2}}=\frac{\mu_0 \mathrm{Iq}}{2 \pi \mathrm{ m}} \int_{\mathrm{x_1}^{\mathrm{x}}\frac{dr}{r}
